SELECT 'gongkao', '自我介绍/求职动机', 'kp-ms-match-self', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "自我认知：自我介绍与求职动机"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "你不需要很完美，但你必须很“匹配”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、自我介绍的“人岗匹配”原则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "千万不要报流水账说自己哪年出生、喜欢听歌看电影！这些考官毫不关心。"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "报考基层岗位：重点强调自己吃苦耐劳、有农村生活经历、在大学参加过支教或基层调研。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "报考专业岗位（如税务/审计）：重点强调自己的专业成绩、数据分析能力、严谨细致的性格。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "报考综合管理岗：重点强调自己在学生会担任干部的组织协调能力和公文写作能力。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、求职动机（为什么考公务员？）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "过于功利或假大空：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不要说“因为公务员稳定福利好”（太功利），也不要说“为了拯救全人类”（太假）。"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "标准答案框架：【家庭熏陶/个人理想】 + 【专业契合/能力自信】 + 【对该岗位的向往与价值认同】。"}]}]}$$ AS jsonb), NULL, '自我介绍/求职动机的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "自我认知", "求职动机"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_match_self", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
